+const form = document.getElementById("notification-form");
+const status = document.getElementById("form-status");
+const radios = Array.from(document.querySelectorAll('input[name="notification-method"]'));
+
+function setError(message) {
+  status.textContent = message;
+  status.dataset.state = "error";
+  radios.forEach((radio) => {
+    radio.setAttribute("aria-invalid", "true");
+  });
+}
+
+function clearError() {
+  status.textContent = "";
+  status.removeAttribute("data-state");
+  radios.forEach((radio) => {
+    radio.removeAttribute("aria-invalid");
+  });
+}
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  const selected = radios.find((radio) => radio.checked);
+
+  if (!selected) {
+    setError("Please choose one notification method before submitting.");
+    radios[0].focus();
+    return;
+  }
+
+  clearError();
+  status.textContent = `You selected ${selected.value}.`;
+});
+
+radios.forEach((radio) => {
+  radio.addEventListener("change", () => {
+    if (radios.some((item) => item.checked)) {
+      clearError();
+    }
+  });
+});
+

