 input[type="radio"]:focus-visible,
 .submit-button:focus-visible,
 .skip-link:focus-visible {
   outline: 3px solid var(--focus);
   outline-offset: 3px;
 }

 .status {
   min-height: 1.5rem;
   margin: 1rem 0 0;
   color: var(--muted);
 }

 .status[data-state="error"] {
   color: var(--danger);
 }

 .submit-button {
   margin-top: 1.25rem;
   padding: 0.9rem 1.25rem;
   border: 1px solid transparent;
   border-radius: 999px;
   background: linear-gradient(180deg, #84bcff 0%, #5a95f0 100%);
   color: #08101e;
   font-weight: 700;
   cursor: pointer;
 }

 .submit-button:hover {
   background: linear-gradient(180deg, #94c6ff 0%, #6ca2fa 100%);
 }

 .submit-button:active {
   transform: translateY(1px);
 }

 @media (max-width: 480px) {
   .card {
     padding: 1.25rem;
   }

   .radio-option {
     align-items: flex-start;
   }
 }

 @media (forced-colors: active) {
   .skip-link,
   .card,
   .radio-option,
   .submit-button {
     forced-color-adjust: auto;
     background: Canvas;
     color: CanvasText;
     border-color: ButtonBorder;
   }

   .skip-link {
     background: Highlight;
     color: HighlightText;
   }

   input[type="radio"]:focus-visible,
   .submit-button:focus-visible,
   .skip-link:focus-visible {
     outline-color: Highlight;
   }
 }

